-- Choices from the review page (https://claude.ai/artifact/NSuKSYBEbjRbLgS17Bztzb), pasted in chat on 22 Oct 2026.
-- Generated by supabase/.local/stage9/make_fix.py; 377 items on 241 businesses.
--
-- Per business: the first chosen email (or phone) fills businesses.email (or .phone) only when that field
-- is empty; every other chosen item is appended, as typed in the sheet (dates as DD/MM/YYYY), to the end
-- of businesses.notes under "From the Mastersheet (archived 22 Oct 2026):". Nothing else changes.
-- Every touched business is copied to cc_phase0_backup (reason 'stage9_mastersheet_2026_10_22') first.
-- Undo: supabase/data-fixes/20261022_stage9_mastersheet_undo.sql
-- Run with psql -v ON_ERROR_STOP=1. It refuses to run twice.

BEGIN;

DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM cc_phase0_backup WHERE reason = 'stage9_mastersheet_2026_10_22') THEN
    RAISE EXCEPTION 'stage9_mastersheet_2026_10_22 has already been applied';
  END IF;
END $$;

