-- every business still exists, is not merged away and has the name Tom saw
DO $$ DECLARE bad text; BEGIN
  SELECT string_agg(DISTINCT m.biz_name, ', ') INTO bad
  FROM _ms m LEFT JOIN businesses b ON b.id = m.biz
  WHERE b.id IS NULL OR b.name IS DISTINCT FROM m.biz_name OR b.merged_into IS NOT NULL;
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'changed since the review: %', bad; END IF;
END $$;

INSERT INTO cc_phase0_backup (table_name, row_id, before_row, reason)
SELECT 'businesses', b.id, to_jsonb(b), 'stage9_mastersheet_2026_10_22' FROM businesses b WHERE b.id IN (SELECT biz FROM _ms);

-- fills: the first email / phone for a business whose own field is empty
CREATE TEMP TABLE _fill ON COMMIT DROP AS
SELECT DISTINCT ON (m.biz, m.kind) m.n, m.biz, m.kind, m.val
FROM _ms m JOIN businesses b ON b.id = m.biz
WHERE (m.kind = 'email' AND coalesce(btrim(b.email), '') = '')
   OR (m.kind = 'phone' AND coalesce(btrim(b.phone), '') = '')
ORDER BY m.biz, m.kind, m.n;

CREATE TEMP TABLE _block ON COMMIT DROP AS
SELECT m.biz, 'From the Mastersheet (archived 22 Oct 2026):' || E'\n'
       || string_agg('- ' || m.label || ': ' || m.val, E'\n' ORDER BY m.n) AS block
FROM _ms m WHERE m.n NOT IN (SELECT n FROM _fill)
GROUP BY m.biz;

UPDATE businesses b SET
  email = coalesce((SELECT f.val FROM _fill f WHERE f.biz = b.id AND f.kind = 'email'), b.email),
  phone = coalesce((SELECT f.val FROM _fill f WHERE f.biz = b.id AND f.kind = 'phone'), b.phone),
  notes = CASE WHEN k.block IS NULL THEN b.notes
               ELSE coalesce(nullif(rtrim(b.notes), '') || E'\n\n', '') || k.block END
FROM (SELECT DISTINCT biz FROM _ms) t LEFT JOIN _block k ON k.biz = t.biz
WHERE b.id = t.biz;

-- checks: every item landed, the start of each note is untouched, and only these businesses changed
DO $$ DECLARE lost int; changed int; started int; BEGIN
  SELECT count(*) INTO lost FROM _ms m JOIN businesses b ON b.id = m.biz
  WHERE NOT (m.n IN (SELECT n FROM _fill) AND m.val = CASE m.kind WHEN 'email' THEN b.email ELSE b.phone END)
    AND position(('- ' || m.label || ': ' || m.val) IN coalesce(b.notes, '')) = 0;
  SELECT count(*) INTO started FROM businesses b JOIN cc_phase0_backup k ON k.row_id = b.id AND k.reason = 'stage9_mastersheet_2026_10_22'
  WHERE left(coalesce(b.notes, ''), length(rtrim(coalesce(k.before_row->>'notes', '')))) <> rtrim(coalesce(k.before_row->>'notes', ''));
  SELECT count(*) INTO changed FROM cc_phase0_backup WHERE reason = 'stage9_mastersheet_2026_10_22';
  IF lost > 0 OR started > 0 OR changed <> 241 THEN
    RAISE EXCEPTION 'check failed: % items missing, % notes altered, % businesses backed up (expected 241)', lost, started, changed;
  END IF;
  RAISE NOTICE 'stage 9: % items on % businesses; % fields filled', (SELECT count(*) FROM _ms), changed, (SELECT count(*) FROM _fill);
END $$;

